create table if not exists board_states (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, state_json jsonb not null default '{}'::jsonb, version int not null default 1, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now()); alter table board_states enable row level security; create unique index if not exists idx_board_states_room on board_states(room_id);
